const TOKEN = $env.HOMELAB_TELEGRAM_BOT_TOKEN, CHAT = String($env.HOMELAB_TELEGRAM_CHAT_ID || '');
const LAN = 'http://192.168.3.201', PVE = 'https://192.168.3.200:8006';
const helpers = this.helpers;
const s = $getWorkflowStaticData('global');
const say = (text) => helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${TOKEN}/sendMessage`, body: { chat_id: CHAT, text, disable_web_page_preview: true }, json: true, timeout: 15000 });
const get = (url, opts = {}) => helpers.httpRequest({ url, json: true, timeout: 20000, ...opts });
const safe = async (fn) => { try { return await fn(); } catch (e) { return null; } };
const lagosNow = () => new Date(new Date().toLocaleString('en-US', { timeZone: 'Africa/Lagos' }));
const pad = (n) => String(n).padStart(2, '0');
const ymd = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const hm = (h) => { const m = Math.round(h * 60); return Math.floor(m / 60) ? `${Math.floor(m / 60)} h ${m % 60} min` : `${m % 60} min`; };
const prom = async (expr) => { const r = await get(`${LAN}:9090/api/v1/query`, { qs: { query: expr } }); const v = r?.data?.result?.[0]?.value?.[1]; return v === undefined ? null : Number(v); };
const pveGet = (path) => get(`${PVE}/api2/json${path}`, { headers: { Authorization: `PVEAPIToken=${$env.HOMEPAGE_VAR_PROXMOX_TOKEN_ID}=${$env.HOMEPAGE_VAR_PROXMOX_TOKEN_SECRET}` }, skipSslCertificateValidation: true }).then(r => r.data);
const ghHeaders = (extra = {}) => ({ Authorization: `Bearer ${$env.HOMELAB_GITHUB_TOKEN || ''}`, Accept: 'application/vnd.github+json', 'User-Agent': 'homelab-n8n', ...extra });
const gh = (path, opts = {}) => { const { headers, ...rest } = opts; return helpers.httpRequest({ url: `https://api.github.com${path}`, json: true, timeout: 20000, headers: ghHeaders(headers), ...rest }); };
const REPO = $env.HOMELAB_GITHUB_REPO || 'theOGpython/homelab';

// Remove downloads stalled for 24h+; Radarr/Sonarr/Lidarr blocklist them and search for another copy.
const STALL_HOURS = 24, MAX_PER_RUN = 5;
const login = await helpers.httpRequest({ method: 'POST', url: `${LAN}:8080/api/v2/auth/login`,
  headers: { 'Content-Type': 'application/x-www-form-urlencoded', Referer: `${LAN}:8080` },
  body: `username=${encodeURIComponent($env.HOMEPAGE_VAR_QBIT_USER || '')}&password=${encodeURIComponent($env.HOMEPAGE_VAR_QBIT_PASS || '')}`,
  returnFullResponse: true, timeout: 15000 });
const cookie = [].concat(login.headers?.['set-cookie'] || []).map(c => c.split(';')[0]).join('; ');
if (!cookie) throw new Error('qBittorrent login failed');
const torrents = await get(`${LAN}:8080/api/v2/torrents/info`, { headers: { Cookie: cookie, Referer: `${LAN}:8080` } });
const now = Date.now() / 1000, limit = STALL_HOURS * 3600;
const stalled = torrents.filter(t => ['stalledDL', 'metaDL'].includes(t.state) && t.progress < 1 &&
  now - (t.last_activity || t.added_on) > limit && now - t.added_on > limit).slice(0, MAX_PER_RUN);
if (!stalled.length) return [];

const ARRS = [
  { name: 'Radarr', url: `${LAN}:7878/api/v3`, key: $env.HOMEPAGE_VAR_RADARR_KEY },
  { name: 'Sonarr', url: `${LAN}:8989/api/v3`, key: $env.HOMEPAGE_VAR_SONARR_KEY },
  { name: 'Lidarr', url: `${LAN}:8686/api/v1`, key: $env.HOMEPAGE_VAR_LIDARR_KEY },
];
const queues = [];
for (const a of ARRS) {
  const q = await safe(() => get(`${a.url}/queue`, { headers: { 'X-Api-Key': a.key || '' }, qs: { pageSize: 500 } }));
  for (const r of (q?.records || [])) if (r.downloadId) queues.push({ arr: a, id: r.id, hash: r.downloadId.toLowerCase(), title: r.title });
}
s.notified = (s.notified || []).filter(h => torrents.some(t => t.hash === h));
const removed = [], unmanaged = [];
for (const t of stalled) {
  const days = Math.floor((now - t.added_on) / 86400);
  const item = queues.find(q => q.hash === t.hash.toLowerCase());
  if (item) {
    const ok = await safe(() => helpers.httpRequest({ method: 'DELETE', url: `${item.arr.url}/queue/${item.id}`,
      headers: { 'X-Api-Key': item.arr.key || '' }, qs: { removeFromClient: true, blocklist: true, skipRedownload: false }, timeout: 30000 }).then(() => true));
    if (ok) removed.push(`• ${t.name.slice(0, 55)} (${Math.round(t.progress * 100)}%, ${days} d) → ${item.arr.name} is searching for another copy`);
  } else if (!s.notified.includes(t.hash)) {
    unmanaged.push(`• ${t.name.slice(0, 55)} (${Math.round(t.progress * 100)}%, ${days} d)`);
    s.notified.push(t.hash);
  }
}
const parts = [];
if (removed.length) parts.push(`🧹 Removed ${removed.length} stalled download${removed.length > 1 ? 's' : ''}:\n${removed.join('\n')}`);
if (unmanaged.length) parts.push(`⏸️ Stalled for over ${STALL_HOURS} h but not from Radarr/Sonarr/Lidarr, so left alone (remove in qBittorrent if unwanted):\n${unmanaged.join('\n')}`);
if (parts.length) await say(parts.join('\n\n'));
return parts.length ? [{ json: { removed: removed.length, unmanaged: unmanaged.length } }] : [];
